import React, { useState, useRef, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Send, Paperclip, ChevronRight, X, PanelRightClose, PanelRightOpen, ArrowRight } from 'lucide-react';
import { sendMessageToGemini } from './services/geminiService';
import { Message, ArtifactData, ArtifactType } from './types';
import { BomView } from './components/Artifacts/BomView';
import { CadView } from './components/Artifacts/CadView';
import { DocumentView } from './components/Artifacts/DocumentView';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [currentArtifact, setCurrentArtifact] = useState<ArtifactData | null>(null);
  const [isArtifactPanelOpen, setIsArtifactPanelOpen] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: input,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    // Prepare history for API
    const history = messages.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }));

    const response = await sendMessageToGemini(history, userMsg.text);

    const modelMsg: Message = {
      id: crypto.randomUUID(),
      role: 'model',
      text: response.text,
      timestamp: Date.now(),
      relatedArtifactId: response.artifact?.id
    };

    setMessages(prev => [...prev, modelMsg]);
    setIsLoading(false);

    if (response.artifact) {
      setCurrentArtifact(response.artifact);
      setIsArtifactPanelOpen(true);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleNewChat = () => {
    setMessages([]);
    setCurrentArtifact(null);
    setIsArtifactPanelOpen(false);
  };

  const toggleArtifactPanel = () => {
    setIsArtifactPanelOpen(!isArtifactPanelOpen);
  };

  // Render content of artifact based on type
  const renderArtifactContent = () => {
    if (!currentArtifact) return <div className="p-8 text-center text-gray-500">No artifact selected</div>;

    switch (currentArtifact.type) {
      case ArtifactType.BOM:
        return <BomView data={currentArtifact.content} />;
      case ArtifactType.CAD_CONCEPT:
        return <CadView data={currentArtifact.content} />;
      case ArtifactType.DOCUMENT:
      case ArtifactType.REVIEW_NOTE:
        return <DocumentView data={currentArtifact.content} />;
      default:
        return <div className="p-4">Unknown Artifact Type</div>;
    }
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-white text-gray-900 font-sans">
      <Sidebar onNewChat={handleNewChat} />

      {/* Main Chat Area */}
      <div className={`flex-1 flex flex-col h-full transition-all duration-300 relative ${isArtifactPanelOpen ? 'w-1/2' : 'w-full'}`}>

        {/* Mobile Header (Hidden on Desktop usually, but good for structure) */}
        <div className="h-14 border-b border-gray-100 flex items-center justify-between px-4 md:hidden">
            <span className="font-serif font-bold">Buildables v3</span>
        </div>

        {/* Chat Scroll Area */}
        <div className="flex-1 overflow-y-auto custom-scrollbar px-4 pt-4 pb-24">
          {messages.length === 0 ? (
             <div className="flex flex-col items-center justify-center h-full max-w-2xl mx-auto text-center opacity-0 animate-fade-in" style={{animation: 'fadeIn 0.5s forwards'}}>
                <div className="w-16 h-16 bg-[#f0eee6] rounded-2xl mb-6 flex items-center justify-center">
                    <span className="font-serif text-3xl font-bold text-gray-700">B</span>
                </div>
                <h1 className="font-serif text-3xl text-gray-800 mb-3">Good afternoon, Engineer.</h1>
                <p className="text-gray-500 mb-8 max-w-md text-lg">
                  I can help you create concepts, source components, or review your engineering documentation.
                </p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 w-full max-w-lg">
                    <button onClick={() => setInput("Generate a BOM for a 3-axis robotic arm prototype")} className="p-3 border rounded-lg text-sm text-gray-600 hover:bg-gray-50 text-left transition-colors">
                        Draft BOM for Robotic Arm
                    </button>
                    <button onClick={() => setInput("Create a CAD concept for a heavy-duty camera mount")} className="p-3 border rounded-lg text-sm text-gray-600 hover:bg-gray-50 text-left transition-colors">
                        Concept: Camera Mount
                    </button>
                    <button onClick={() => setInput("Review design assumptions for a high-temp enclosure")} className="p-3 border rounded-lg text-sm text-gray-600 hover:bg-gray-50 text-left transition-colors">
                        Review Enclosure Thermal Design
                    </button>
                    <button onClick={() => setInput("Find alternative suppliers for STM32F405")} className="p-3 border rounded-lg text-sm text-gray-600 hover:bg-gray-50 text-left transition-colors">
                        Source STM32 Alternatives
                    </button>
                </div>
             </div>
          ) : (
            <div className="max-w-3xl mx-auto space-y-6 py-8">
              {messages.map((msg) => (
                <div key={msg.id} className={`flex gap-4 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  {msg.role === 'model' && (
                    <div className="w-8 h-8 rounded-full bg-brand-accent text-white flex-shrink-0 flex items-center justify-center text-xs font-serif font-bold mt-1">
                      B
                    </div>
                  )}

                  <div className={`flex flex-col max-w-[80%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                    {msg.role === 'user' ? (
                        <div className="bg-[#f0eee6] text-gray-800 px-5 py-3 rounded-2xl rounded-tr-sm text-[15px] leading-relaxed">
                            {msg.text}
                        </div>
                    ) : (
                        <div className="text-gray-800 px-1 py-1 text-[15px] leading-relaxed">
                            {msg.text.split('\n').map((line, i) => (
                                <p key={i} className="mb-2 last:mb-0">{line}</p>
                            ))}
                            {msg.relatedArtifactId && (
                                <button 
                                    onClick={() => setIsArtifactPanelOpen(true)}
                                    className="mt-3 flex items-center gap-2 text-xs font-medium text-brand-accent hover:text-orange-700 bg-orange-50 px-3 py-2 rounded-lg border border-orange-100 transition-colors"
                                >
                                    <PanelRightOpen size={14} />
                                    View Generated Artifact
                                    <ArrowRight size={12} />
                                </button>
                            )}
                        </div>
                    )}
                  </div>
                </div>
              ))}
              {isLoading && (
                  <div className="flex gap-4">
                     <div className="w-8 h-8 rounded-full bg-brand-accent text-white flex-shrink-0 flex items-center justify-center text-xs font-serif font-bold mt-1">B</div>
                     <div className="flex items-center gap-1 mt-3">
                        <div className="w-2 h-2 bg-gray-300 rounded-full animate-bounce" style={{animationDelay: '0s'}}></div>
                        <div className="w-2 h-2 bg-gray-300 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                        <div className="w-2 h-2 bg-gray-300 rounded-full animate-bounce" style={{animationDelay: '0.4s'}}></div>
                     </div>
                  </div>
              )}
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Input Area */}
        <div className="p-4 bg-white/80 backdrop-blur-md sticky bottom-0 z-10">
          <div className="max-w-3xl mx-auto bg-white border border-gray-200 rounded-xl shadow-sm focus-within:ring-2 focus-within:ring-brand-accent/20 focus-within:border-brand-accent transition-all overflow-hidden flex flex-col">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Ask Copilot about sourcing, CAD, or specs..."
              className="w-full max-h-40 p-4 resize-none outline-none text-base bg-transparent custom-scrollbar"
              rows={1}
              style={{ minHeight: '60px' }}
            />
            <div className="flex justify-between items-center px-3 pb-3 pt-0">
               <button className="p-2 text-gray-400 hover:text-gray-600 rounded-lg hover:bg-gray-100 transition-colors">
                 <Paperclip size={18} />
               </button>
               <button 
                onClick={handleSendMessage}
                disabled={!input.trim() || isLoading}
                className={`p-2 rounded-lg transition-all duration-200 ${input.trim() ? 'bg-brand-accent text-white shadow-md' : 'bg-gray-100 text-gray-400'}`}
               >
                 <Send size={18} />
               </button>
            </div>
          </div>
          <p className="text-center text-xs text-gray-400 mt-2">Buildables v3 can make mistakes. Verify component specs.</p>
        </div>

      </div>

      {/* Right Artifact Panel (v0 style) */}
      {isArtifactPanelOpen && (
