}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ArtifactType, ArtifactData, LLMResponseParsed, UserContext } from "../types";

// Helper to extract JSON artifact from text if present
// We instruct the model to wrap artifacts in ```json tag with a specific structure
const parseArtifactFromResponse = (text: string): LLMResponseParsed => {
  const artifactRegex = /```json\s*({[\s\S]*?"_isArtifact":\s*true[\s\S]*?})\s*```/;
  const match = text.match(artifactRegex);

  if (match && match[1]) {
    try {
      const artifactJson = JSON.parse(match[1]);
      const cleanText = text.replace(match[0], "").trim();

      const artifact: ArtifactData = {
        id: crypto.randomUUID(),
        title: artifactJson.title || "Generated Artifact",
        type: artifactJson.type as ArtifactType,
        content: artifactJson.content
      };

      return {
        text: cleanText,
        artifact: artifact
      };
    } catch (e) {
      console.error("Failed to parse artifact JSON", e);
      return { text: text };
    }
  }

  return { text: text };
};

export const sendMessageToGemini = async (
  history: { role: string; parts: { text: string }[] }[],
  newMessage: string,
  userContext?: UserContext | null
): Promise<LLMResponseParsed> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key not found");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const contextInstruction = userContext ? `
  **USER CONTEXT PROFILE:**
  The user has configured the following engineering environment. You must tailor your advice, resource selection, and risk analysis to fit this profile:
  - **Primary Workflow:** ${userContext.workflow}
  - **Available Resources:** ${userContext.resources.join(', ')}
  - **Product Lifecycle:** ${userContext.lifecycle}

  *Example of tailoring:* If the user has "3D Printing Farm" but not "CNC", prioritize additive manufacturing design rules (DFAM) over subtractive ones unless explicitly asked.
  ` : '';

  const systemInstruction = `
You are Buildables v3, a specialized Engineering Copilot. 
Your goal is to assist mechanical engineers with design, sourcing, and documentation.

${contextInstruction}

You have three modes of operation (Pillars):
1. **Concept Formation**: Generating conceptual ideas using existing parts.
2. **Sourcing & BOM**: Creating Bills of Materials with supplier context (DigiKey, etc.).
3. **Engineering Copilot**: Reviewing designs, checking standards, and documenting logic.

**CRITICAL INSTRUCTION FOR ARTIFACT GENERATION:**
If the user asks for a specific deliverable (like a BOM, a CAD concept, a Design Review, or a Specification Document), you MUST generate a JSON block inside your response. 
The JSON block must be wrapped in \`\`\`json \`\`\` and include "_isArtifact": true.

**Schemas for Artifacts:**

1. **BOM (Bill of Materials):**
\`\`\`json
{
  "_isArtifact": true,
  "type": "BOM",
  "title": "BOM: [Assembly Name]",
  "content": {
    "items": [
      { "id": "1", "partNumber": "...", "description": "...", "manufacturer": "...", "quantity": 1, "unitPrice": 0.00, "leadTime": "3 days", "supplier": "DigiKey", "notes": "..." }
    ],
    "totalCost": 100.00
  }
}
\`\`\`

2. **CAD Concept (Modo.is style):**
\`\`\`json
{
  "_isArtifact": true,
  "type": "CAD_CONCEPT",
  "title": "Concept: [Concept Name]",
  "content": {
    "conceptName": "...",
    "constraints": ["Material: AL6061", "Max Load: 50N"],
    "components": ["NEMA 17 Stepper", "GT2 Belt", "Linear Rail MGN12"],
    "visualStyle": "shaded"
  }
}
\`\`\`

3. **Document/Review:**
\`\`\`json
{
  "_isArtifact": true,
  "type": "DOCUMENT",
  "title": "Review: [Topic]",
  "content": {
    "title": "...",
    "sections": [
      { "heading": "Design Assumptions", "body": "..." },
      { "heading": "Risk Analysis", "body": "..." }
    ]
  }
}
\`\`\`

If no specific artifact is needed, just reply with text. 
Maintain a professional, engineering-focused tone. Concise, precise, and helpful.
`;

  try {
    const model = 'gemini-3-flash-preview'; 
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: [
        { role: 'user', parts: [{ text: systemInstruction }] }, // Prepend system prompt
        ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: h.parts })),
        { role: 'user', parts: [{ text: newMessage }] }
      ],
      config: {
        temperature: 0.2, // Low temperature for engineering precision
      }
    });

    const textResponse = response.text || "I'm having trouble processing that request.";
    return parseArtifactFromResponse(textResponse);

  } catch (error) {
    console.error("Gemini API Error:", error);
    return { text: "Error communicating with the Engineering Copilot. Please check your connection or API key." };
  }
};

import React, { useState } from 'react';
import { UserContext } from '../types';
import { ArrowRight, Check, Briefcase, Wrench, RefreshCw, Cpu, Layers } from 'lucide-react';

interface OnboardingModalProps {
  onComplete: (context: UserContext) => void;
}

export const OnboardingModal: React.FC<OnboardingModalProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [workflow, setWorkflow] = useState('');
  const [resources, setResources] = useState<string[]>([]);
  const [lifecycle, setLifecycle] = useState('');

  const workflows = [
    { id: 'rapid_proto', label: 'Rapid Prototyping', desc: 'Speed and iteration over perfection', icon: <Cpu size={20} /> },
    { id: 'production', label: 'Production Engineering', desc: 'DFM, cost reduction, reliability', icon: <Briefcase size={20} /> },
    { id: 'r_and_d', label: 'Research & Development', desc: 'Exploratory, high uncertainty', icon: <Layers size={20} /> },
  ];

  const resourceOptions = [
    'Internal Machine Shop (CNC)',
    '3D Printing Farm (FDM/SLA)',
    'Certified Testing Lab',
    'PCB Assembly Line',
    'Sheet Metal Fabrication',
    'Procurement Team'
  ];

  const lifecycles = [
    { id: 'agile', label: 'Agile Hardware', desc: 'Sprints, MVP iterations' },
    { id: 'stage_gate', label: 'Stage-Gate / Waterfall', desc: 'Structured milestones (PDR, CDR)' },
    { id: 'v_model', label: 'V-Model', desc: 'Strict systems engineering (Medical/Auto)' },
  ];

  const toggleResource = (res: string) => {
    setResources(prev => 
      prev.includes(res) ? prev.filter(r => r !== res) : [...prev, res]
    );
  };

  const handleNext = () => {
    if (step < 3) {
      setStep(step + 1);
    } else {
      onComplete({
        workflow: workflows.find(w => w.id === workflow)?.label || workflow,
        resources,
        lifecycle: lifecycles.find(l => l.id === lifecycle)?.label || lifecycle
      });
    }
  };

  const isStepValid = () => {
    if (step === 1) return !!workflow;
    if (step === 2) return resources.length > 0;
    if (step === 3) return !!lifecycle;
    return false;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-brand-darkBlue/60 backdrop-blur-sm p-4 animate-in fade-in duration-300">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="bg-brand-gray border-b border-gray-200 p-6 flex items-center justify-between">
          <div>
            <h2 className="text-xl font-bold text-brand-darkBlue">Setup your Workspace</h2>
            <p className="text-sm text-gray-500 mt-1">Configure Buildables v3 for your specific needs.</p>
          </div>
          <div className="flex items-center gap-2">
            {[1, 2, 3].map(i => (
              <div key={i} className={`h-2 w-2 rounded-full transition-colors ${step >= i ? 'bg-brand-blue' : 'bg-gray-300'}`} />
            ))}
          </div>
        </div>

        {/* Body */}
        <div className="p-8 flex-1 overflow-y-auto">
          {step === 1 && (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <h3 className="text-lg font-semibold text-brand-darkBlue mb-4">1. What describes your primary workflow?</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {workflows.map((opt) => (
                  <button
                    key={opt.id}
                    onClick={() => setWorkflow(opt.id)}
                    className={`flex flex-col items-start p-4 border rounded-xl text-left transition-all ${
                      workflow === opt.id 
                        ? 'border-brand-blue bg-brand-lightBlue ring-1 ring-brand-blue' 
                        : 'border-gray-200 hover:border-brand-blue/50 hover:bg-gray-50'
                    }`}
                  >
                    <div className={`p-2 rounded-lg mb-3 ${workflow === opt.id ? 'bg-brand-blue text-white' : 'bg-gray-100 text-gray-500'}`}>
                      {opt.icon}
                    </div>
                    <div className="font-bold text-brand-darkBlue text-sm">{opt.label}</div>
                    <div className="text-xs text-gray-500 mt-1">{opt.desc}</div>
                  </button>
                ))}
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <h3 className="text-lg font-semibold text-brand-darkBlue mb-4">2. What resources do you have access to?</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {resourceOptions.map((res) => (
                  <button
                    key={res}
                    onClick={() => toggleResource(res)}
                    className={`flex items-center p-4 border rounded-xl transition-all ${
                      resources.includes(res)
                        ? 'border-brand-blue bg-brand-lightBlue text-brand-blue'
                        : 'border-gray-200 hover:border-brand-blue/50 text-gray-600'
                    }`}
                  >
                    <div className={`w-5 h-5 rounded border mr-3 flex items-center justify-center ${
                      resources.includes(res) ? 'bg-brand-blue border-brand-blue' : 'border-gray-300 bg-white'
                    }`}>
                      {resources.includes(res) && <Check size={14} className="text-white" />}
                    </div>
                    <span className="text-sm font-medium">{res}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {step === 3 && (
             <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
             <h3 className="text-lg font-semibold text-brand-darkBlue mb-4">3. Which product lifecycle do you follow?</h3>
             <div className="space-y-3">
               {lifecycles.map((opt) => (
                 <button
                   key={opt.id}
                   onClick={() => setLifecycle(opt.id)}
                   className={`w-full flex items-center justify-between p-4 border rounded-xl text-left transition-all ${
                     lifecycle === opt.id 
                       ? 'border-brand-blue bg-brand-lightBlue ring-1 ring-brand-blue' 
                       : 'border-gray-200 hover:border-brand-blue/50 hover:bg-gray-50'
                   }`}
                 >
                   <div>
                     <div className="font-bold text-brand-darkBlue text-sm">{opt.label}</div>
                     <div className="text-xs text-gray-500 mt-0.5">{opt.desc}</div>
                   </div>
                   {lifecycle === opt.id && <div className="text-brand-blue"><Check size={20} /></div>}
                 </button>
               ))}
             </div>
           </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-6 border-t border-gray-200 flex justify-between items-center bg-gray-50">
          <button 
            onClick={() => step > 1 && setStep(step - 1)}
            className={`text-sm font-medium text-gray-500 hover:text-brand-darkBlue px-4 py-2 ${step === 1 ? 'invisible' : ''}`}
          >
            Back
          </button>

          <button
            onClick={handleNext}
            disabled={!isStepValid()}
            className={`flex items-center gap-2 px-6 py-2.5 rounded-lg text-sm font-bold text-white transition-all ${
              isStepValid() 
                ? 'bg-brand-orange hover:bg-orange-600 shadow-md transform hover:-translate-y-0.5' 
                : 'bg-gray-300 cursor-not-allowed'
            }`}
          >
            {step === 3 ? 'Finish Setup' : 'Continue'}
            <ArrowRight size={16} />
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Send, Paperclip, ChevronRight, X, PanelRightClose, PanelRightOpen, ArrowRight } from 'lucide-react';
import { sendMessageToGemini } from './services/geminiService';
import { Message, ArtifactData, ArtifactType, UserContext } from './types';
import { BomView } from './components/Artifacts/BomView';
import { CadView } from './components/Artifacts/CadView';
import { DocumentView } from './components/Artifacts/DocumentView';
import { OnboardingModal } from './components/OnboardingModal';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [currentArtifact, setCurrentArtifact] = useState<ArtifactData | null>(null);
  const [isArtifactPanelOpen, setIsArtifactPanelOpen] = useState(false);
  const [userContext, setUserContext] = useState<UserContext | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(true);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: input,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    // Prepare history for API
    const history = messages.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }));

    // Pass userContext to the service
    const response = await sendMessageToGemini(history, userMsg.text, userContext);

    const modelMsg: Message = {
      id: crypto.randomUUID(),
      role: 'model',
      text: response.text,
      timestamp: Date.now(),
      relatedArtifactId: response.artifact?.id
    };

    setMessages(prev => [...prev, modelMsg]);
    setIsLoading(false);

    if (response.artifact) {
      setCurrentArtifact(response.artifact);
      setIsArtifactPanelOpen(true);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleNewChat = () => {
    setMessages([]);
    setCurrentArtifact(null);
    setIsArtifactPanelOpen(false);
  };

  const toggleArtifactPanel = () => {
    setIsArtifactPanelOpen(!isArtifactPanelOpen);
  };

  const handleOnboardingComplete = (context: UserContext) => {
    setUserContext(context);
    setShowOnboarding(false);

    // Optional: Add a system welcome message based on context
    const welcomeMsg: Message = {
      id: crypto.randomUUID(),
      role: 'model',
      text: `Workspace configured for **${context.workflow}**. \nI've noted your access to ${context.resources.join(', ')} and your ${context.lifecycle} requirements. \n\nHow can I help you start your engineering task today?`,
      timestamp: Date.now()
    };
    setMessages([welcomeMsg]);
  };

  // Render content of artifact based on type
  const renderArtifactContent = () => {
    if (!currentArtifact) return <div className="p-8 text-center text-gray-500">No artifact selected</div>;

    switch (currentArtifact.type) {
      case ArtifactType.BOM:
        return <BomView data={currentArtifact.content} />;
      case ArtifactType.CAD_CONCEPT:
        return <CadView data={currentArtifact.content} />;
      case ArtifactType.DOCUMENT:
      case ArtifactType.REVIEW_NOTE:
        return <DocumentView data={currentArtifact.content} />;
      default:
        return <div className="p-4">Unknown Artifact Type</div>;
    }
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-white text-brand-darkBlue font-sans">
      {showOnboarding && <OnboardingModal onComplete={handleOnboardingComplete} />}

      <Sidebar onNewChat={handleNewChat} />

      {/* Main Chat Area */}
      <div className={`flex-1 flex flex-col h-full transition-all duration-300 relative ${isArtifactPanelOpen ? 'w-1/2' : 'w-full'}`}>

        {/* Mobile Header (Hidden on Desktop usually, but good for structure) */}
        <div className="h-14 border-b border-gray-100 flex items-center justify-between px-4 md:hidden">
            <span className="font-bold text-brand-blue">Buildables v3</span>
        </div>

        {/* Chat Scroll Area */}
        <div className="flex-1 overflow-y-auto custom-scrollbar px-4 pt-4 pb-24">
          {messages.length === 0 ? (
             <div className="flex flex-col items-center justify-center h-full max-w-2xl mx-auto text-center opacity-0 animate-fade-in" style={{animation: 'fadeIn 0.5s forwards'}}>
                <div className="w-16 h-16 bg-brand-lightBlue rounded-2xl mb-6 flex items-center justify-center">
                    <span className="font-sans text-3xl font-bold text-brand-blue">B</span>
                </div>
                <h1 className="font-bold text-3xl text-brand-darkBlue mb-3">Good afternoon, Engineer.</h1>
                <p className="text-gray-500 mb-8 max-w-md text-lg">
                  I can help you create concepts, source components, or review your engineering documentation.
                </p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 w-full max-w-lg">
                    <button onClick={() => setInput("Generate a BOM for a 3-axis robotic arm prototype")} className="p-4 border border-gray-200 rounded-xl text-sm text-gray-600 hover:border-brand-blue hover:text-brand-blue hover:bg-brand-lightBlue/30 text-left transition-all">
                        Draft BOM for Robotic Arm
                    </button>
                    <button onClick={() => setInput("Create a CAD concept for a heavy-duty camera mount")} className="p-4 border border-gray-200 rounded-xl text-sm text-gray-600 hover:border-brand-blue hover:text-brand-blue hover:bg-brand-lightBlue/30 text-left transition-all">
                        Concept: Camera Mount
                    </button>
                    <button onClick={() => setInput("Review design assumptions for a high-temp enclosure")} className="p-4 border border-gray-200 rounded-xl text-sm text-gray-600 hover:border-brand-blue hover:text-brand-blue hover:bg-brand-lightBlue/30 text-left transition-all">
                        Review Enclosure Thermal Design
                    </button>
                    <button onClick={() => setInput("Find alternative suppliers for STM32F405")} className="p-4 border border-gray-200 rounded-xl text-sm text-gray-600 hover:border-brand-blue hover:text-brand-blue hover:bg-brand-lightBlue/30 text-left transition-all">
                        Source STM32 Alternatives
                    </button>
                </div>
             </div>
          ) : (
            <div className="max-w-3xl mx-auto space-y-6 py-8">
              {messages.map((msg) => (
                <div key={msg.id} className={`flex gap-4 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  {msg.role === 'model' && (
                    <div className="w-8 h-8 rounded-full bg-brand-blue text-white flex-shrink-0 flex items-center justify-center text-xs font-bold mt-1">
                      B
                    </div>
                  )}

                  <div className={`flex flex-col max-w-[80%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                    {msg.role === 'user' ? (
                        <div className="bg-brand-lightBlue text-brand-darkBlue px-5 py-3 rounded-2xl rounded-tr-sm text-[15px] leading-relaxed border border-blue-100">
                            {msg.text}
                        </div>
                    ) : (
                        <div className="text-brand-darkBlue px-1 py-1 text-[15px] leading-relaxed">
                            {msg.text.split('\n').map((line, i) => (
                                <p key={i} className="mb-2 last:mb-0">{line}</p>
                            ))}
                            {msg.relatedArtifactId && (
                                <button 
                                    onClick={() => setIsArtifactPanelOpen(true)}
                                    className="mt-3 flex items-center gap-2 text-xs font-bold text-brand-orange hover:text-orange-700 bg-orange-50 px-3 py-2 rounded-lg border border-orange-100 transition-colors"
                                >
                                    <PanelRightOpen size={14} />
                                    View Generated Artifact
                                    <ArrowRight size={12} />
                                </button>
                            )}
                        </div>
                    )}
                  </div>
                </div>
              ))}
              {isLoading && (
                  <div className="flex gap-4">
                     <div className="w-8 h-8 rounded-full bg-brand-blue text-white flex-shrink-0 flex items-center justify-center text-xs font-bold mt-1">B</div>
                     <div className="flex items-center gap-1 mt-3">
                        <div className="w-2 h-2 bg-brand-blue/40 rounded-full animate-bounce" style={{animationDelay: '0s'}}></div>
                        <div className="w-2 h-2 bg-brand-blue/40 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                        <div className="w-2 h-2 bg-brand-blue/40 rounded-full animate-bounce" style={{animationDelay: '0.4s'}}></div>
                     </div>
                  </div>
              )}
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Input Area */}
        <div className="p-4 bg-white sticky bottom-0 z-10">
          <div className="max-w-3xl mx-auto bg-white border border-gray-300 rounded-xl shadow-sm focus-within:ring-2 focus-within:ring-brand-blue/20 focus-within:border-brand-blue transition-all overflow-hidden flex flex-col">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Ask Copilot about sourcing, CAD, or specs..."
              className="w-full max-h-40 p-4 resize-none outline-none text-base bg-transparent custom-scrollbar text-brand-darkBlue placeholder-gray-400"
              rows={1}
              style={{ minHeight: '60px' }}
            />
            <div className="flex justify-between items-center px-3 pb-3 pt-0">
               <button className="p-2 text-gray-400 hover:text-brand-blue rounded-lg hover:bg-brand-lightBlue transition-colors">
                 <Paperclip size={18} />
               </button>
               <button 
                onClick={handleSendMessage}
                disabled={!input.trim() || isLoading}
                className={`p-2 rounded-lg transition-all duration-200 ${input.trim() ? 'bg-brand-blue text-white shadow-md hover:bg-blue-700' : 'bg-gray-100 text-gray-400'}`}
               >
                 <Send size={18} />
               </button>
            </div>
          </div>
          <p className="text-center text-xs text-gray-400 mt-2">Buildables v3 can make mistakes. Verify component specs.</p>
        </div>

      </div>

      {/* Right Artifact Panel (v0 style) */}
      {isArtifactPanelOpen && (
        <div className="w-[45%] h-full border-l border-gray-200 bg-white shadow-xl flex flex-col animate-slide-in-right transform transition-transform duration-300">
          <div className="h-12 border-b border-gray-100 flex items-center justify-between px-4 bg-brand-gray">
            <div className="flex items-center gap-2">
                <span className="text-xs font-bold uppercase tracking-wider text-brand-blue bg-brand-lightBlue px-2 py-0.5 rounded">
                    {currentArtifact?.type || 'ARTIFACT'}
                </span>
                <span className="text-sm font-bold text-brand-darkBlue truncate max-w-[200px]">
                    {currentArtifact?.title}
                </span>
            </div>
            <div className="flex items-center gap-1">
                 <button onClick={toggleArtifactPanel} className="p-2 text-gray-400 hover:text-brand-darkBlue hover:bg-gray-100 rounded">
                    <PanelRightClose size={18} />
                 </button>
                 <button onClick={() => setIsArtifactPanelOpen(false)} className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded">
                    <X size={18} />
                 </button>
            </div>
          </div>

          <div className="flex-1 overflow-hidden relative">
            {renderArtifactContent()}
          </div>
        </div>
      )}

      {/* Toggle Button for panel if closed but artifact exists */}
      {!isArtifactPanelOpen && currentArtifact && (
          <div className="absolute top-4 right-4 z-20">
              <button 
                onClick={() => setIsArtifactPanelOpen(true)}
                className="bg-white border border-gray-200 shadow-lg p-2 rounded-lg text-brand-blue hover:bg-brand-lightBlue transition-all"
              >
                  <PanelRightOpen size={20} />
              </button>
          </div>
      )}

      {/* CSS Animation for fade-in */}
      <style>{`
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default App;

export type Role = 'user' | 'model';

export enum ArtifactType {
  BOM = 'BOM',
  CAD_CONCEPT = 'CAD_CONCEPT',
  DOCUMENT = 'DOCUMENT',
  REVIEW_NOTE = 'REVIEW_NOTE'
}

export interface ArtifactData {
  title: string;
  type: ArtifactType;
  content: any; // Flexible content structure based on type
