          )}
        </div>

        {/* Input Area */}
        <div className="p-4 bg-white sticky bottom-0 z-10">
            {/* Quick Actions Bar */}
            {messages.length > 0 && !isLoading && (
                <div className="max-w-3xl mx-auto flex gap-2 mb-3 overflow-x-auto pb-1 no-scrollbar">
                    {getQuickActions().map((action, i) => (
