import React, { useMemo } from 'react';
import { MessageSquarePlus, Clock, Settings, BookOpen, Database, Cpu, LayoutGrid, MoreHorizontal, Trash2, Archive } from 'lucide-react';
import { Pillar, ProjectSummary } from '../types';

interface SidebarProps {
  onNewChat: () => void;
  activePillar: Pillar;
  onPillarChange: (pillar: Pillar) => void;
  activeView: 'chat' | 'dashboard';
  onOpenDashboard: () => void;
  onOpenSettings: () => void;
  recentProjects: ProjectSummary[];
  onOpenProject: (id: string) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  onNewChat, 
  activePillar, 
  onPillarChange,
  activeView,
  onOpenDashboard,
  onOpenSettings,
  recentProjects,
  onOpenProject
}) => {

  const getButtonClass = (pillar: Pillar) => {
    const isActive = activePillar === pillar && activeView === 'chat';
    return `w-full flex items-center gap-3 px-3 py-2 rounded-md text-sm text-left transition-colors font-medium ${
      isActive 
        ? 'bg-brand-lightBlue text-brand-blue' 
        : 'text-gray-600 hover:bg-gray-200'
    }`;
  };

  // Group projects by date
  const groupedProjects = useMemo(() => {
    const groups: { [key: string]: ProjectSummary[] } = {
        'Today': [],
        'Yesterday': [],
        'Previous 7 Days': [],
        'Older': []
    };

    const today = new Date();
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const lastWeek = new Date();
    lastWeek.setDate(lastWeek.getDate() - 7);

    recentProjects.forEach(p => {
        const d = new Date(p.lastModified);
        // Reset times for date comparison
        const dDate = new Date(d.getFullYear(), d.getMonth(), d.getDate());
        const tDate = new Date(today.getFullYear(), today.getMonth(), today.getDate());
        const yDate = new Date(yesterday.getFullYear(), yesterday.getMonth(), yesterday.getDate());

        if (dDate.getTime() === tDate.getTime()) {
            groups['Today'].push(p);
        } else if (dDate.getTime() === yDate.getTime()) {
            groups['Yesterday'].push(p);
        } else if (d > lastWeek) {
            groups['Previous 7 Days'].push(p);
        } else {
            groups['Older'].push(p);
        }
    });

    return groups;
  }, [recentProjects]);

  return (
    <div className="w-64 bg-brand-gray h-screen flex flex-col border-r border-gray-200 flex-shrink-0 hidden md:flex font-sans">
      <div className="p-4 pt-6">
        <div className="flex items-center gap-2 mb-8 px-2 cursor-pointer group" onClick={onOpenDashboard}>
            <div className="w-8 h-8 bg-brand-blue rounded-lg flex items-center justify-center group-hover:bg-blue-700 transition-colors">
                <span className="text-white font-sans font-bold text-lg">B</span>
            </div>
            <span className="font-bold text-brand-darkBlue tracking-tight group-hover:text-brand-blue transition-colors">Buildables</span>
        </div>

        <button 
            onClick={onNewChat}
            className="w-full flex items-center gap-3 px-4 py-3 bg-white border border-gray-200 rounded-lg shadow-sm hover:border-brand-blue hover:text-brand-blue transition-all text-sm font-medium text-gray-700 mb-6 group"
        >
            <MessageSquarePlus size={18} className="text-brand-orange group-hover:scale-110 transition-transform" />
            New Project
        </button>

        <div className="space-y-1">
            <div className="px-3 py-2 text-xs font-semibold text-gray-400 uppercase tracking-wider">Modes</div>
            <button 
              onClick={() => onPillarChange('concept')}
              className={getButtonClass('concept')}
            >
                <Cpu size={16} /> Concept Formation
            </button>
            <button 
              onClick={() => onPillarChange('sourcing')}
              className={getButtonClass('sourcing')}
            >
                <Database size={16} /> Sourcing & BOM
            </button>
            <button 
              onClick={() => onPillarChange('copilot')}
              className={getButtonClass('copilot')}
            >
                <BookOpen size={16} /> Engineering Copilot
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-2 custom-scrollbar">
         <div className="flex items-center justify-between px-3 py-2 mt-4 sticky top-0 bg-brand-gray z-10">
            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Recents</span>
            <button onClick={onOpenDashboard} className="text-xs text-brand-blue hover:underline" title="View All">View All</button>
         </div>

         <div className="space-y-4 mt-1 pb-4">
            {Object.entries(groupedProjects).map(([label, projects]: [string, ProjectSummary[]]) => (
                projects.length > 0 && (
                    <div key={label}>
                        <div className="px-3 py-1 text-[10px] font-bold text-gray-400/80 uppercase tracking-wider mb-1">{label}</div>
                        <div className="space-y-0.5">
                            {projects.map(project => (
                                <button 
                                    key={project.id}
                                    onClick={() => onOpenProject(project.id)}
                                    className="w-full text-left px-3 py-2 rounded-md hover:bg-gray-200 text-sm text-gray-600 transition-colors flex items-center gap-2 group relative"
                                >
                                   <span className="text-gray-400 group-hover:text-brand-darkBlue transition-colors flex-shrink-0">
                                      {project.pillar === 'concept' && <Cpu size={14}/>}
                                      {project.pillar === 'sourcing' && <Database size={14}/>}
                                      {project.pillar === 'copilot' && <BookOpen size={14}/>}
                                   </span>
                                   <span className="truncate flex-1 font-medium group-hover:text-brand-darkBlue">{project.title}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )
            ))}
            {recentProjects.length === 0 && (
                <div className="px-3 py-4 text-xs text-gray-400 italic text-center">
                    No recent projects.
                </div>
            )}
         </div>
      </div>

      <div className="p-4 border-t border-gray-200">
        <button onClick={onOpenSettings} className="w-full flex items-center gap-3 px-3 py-2 rounded-md hover:bg-gray-200 text-sm text-gray-700 transition-colors group">
            <div className="w-8 h-8 rounded-full bg-brand-darkBlue text-white flex items-center justify-center text-xs group-hover:bg-brand-blue transition-colors ring-2 ring-white shadow-sm">JD</div>
            <div className="flex-1 text-left overflow-hidden">
                <div className="font-medium text-brand-darkBlue truncate">John Doe</div>
                <div className="text-[10px] text-gray-500 truncate">Pro Plan</div>
            </div>
            <Settings size={16} className="text-gray-400 group-hover:text-brand-blue" />
        </button>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Send, Paperclip, ChevronRight, X, PanelRightClose, PanelRightOpen, ArrowRight, Sparkles, FileText, XCircle, Box, Cpu, Shield, Layers, List, Search, AlertTriangle, DollarSign, Eye, Scale, Calculator } from 'lucide-react';
import { sendMessageToGemini } from './services/geminiService';
import { Message, ArtifactData, ArtifactType, UserContext, Pillar, AppSettings, ProjectSummary } from './types';
import { BomView } from './components/Artifacts/BomView';
import { CadView } from './components/Artifacts/CadView';
import { DocumentView } from './components/Artifacts/DocumentView';
import { OnboardingModal } from './components/OnboardingModal';
import { SettingsModal } from './components/SettingsModal';
import { Dashboard } from './components/Dashboard';

// Mock Data for Dashboard
const MOCK_PROJECTS: ProjectSummary[] = [
    { id: '1', title: 'Gearbox Assembly v2', pillar: 'concept', lastModified: Date.now() - 3600000, preview: 'Concept generation for a high-torque planetary gearbox with 20:1 reduction ratio.' },
    { id: '2', title: 'NEMA 17 Mount Stress Analysis', pillar: 'copilot', lastModified: Date.now() - 86400000, preview: 'Reviewing FEA constraints for the new aluminium bracket design.' },
    { id: '3', title: 'Robotic Arm BOM', pillar: 'sourcing', lastModified: Date.now() - 432000000, preview: 'Sourcing list for 6-DOF arm including servos, controllers, and bearings.' },
    { id: '4', title: 'Gripper Mechanism', pillar: 'concept', lastModified: Date.now() - 500000000, preview: 'Compliant mechanism design for soft robotics gripper.' },
];

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [currentArtifact, setCurrentArtifact] = useState<ArtifactData | null>(null);
  const [isArtifactPanelOpen, setIsArtifactPanelOpen] = useState(false);
  const [userContext, setUserContext] = useState<UserContext | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(true);
  const [activePillar, setActivePillar] = useState<Pillar>('copilot');
  const [attachedFiles, setAttachedFiles] = useState<string[]>([]);

  // Navigation State
  const [currentView, setCurrentView] = useState<'chat' | 'dashboard'>('chat');

  // Settings State
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [appSettings, setAppSettings] = useState<AppSettings>({
      unitSystem: 'metric',
      standard: 'iso',
      theme: 'light',
      username: 'John Doe'
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async (text: string = input) => {
    if ((!text.trim() && attachedFiles.length === 0) || isLoading) return;

    let fullText = text;
    if (attachedFiles.length > 0) {
        fullText += `\n\n[Attached Context Files: ${attachedFiles.join(', ')}]`;
    }

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: fullText,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedFiles([]); // Clear attachments
    setIsLoading(true);

    // Prepare history for API
    const history = messages.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }));

    // Pass userContext to the service
    const response = await sendMessageToGemini(history, userMsg.text, userContext, activePillar);

    const modelMsg: Message = {
      id: crypto.randomUUID(),
      role: 'model',
      text: response.text,
      timestamp: Date.now(),
      relatedArtifactId: response.artifact?.id
    };

    setMessages(prev => [...prev, modelMsg]);
    setIsLoading(false);

    if (response.artifact) {
      setCurrentArtifact(response.artifact);
      setIsArtifactPanelOpen(true);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleNewChat = (pillar: Pillar = 'copilot') => {
    setActivePillar(pillar);
    setMessages([]);
    setCurrentArtifact(null);
    setIsArtifactPanelOpen(false);
    setCurrentView('chat');
  };

  const handleOpenProject = (id: string) => {
    // In a real app, load project data here
    setCurrentView('chat');
    // Just simulating a load
    const proj = MOCK_PROJECTS.find(p => p.id === id);
    if(proj) {
        setActivePillar(proj.pillar);
        setMessages([{
            id: 'mock-load',
            role: 'user',
            text: `Opening project: ${proj.title}`,
            timestamp: Date.now()
        }, {
            id: 'mock-load-response',
            role: 'model',
            text: `I've loaded the context for **${proj.title}**. We were discussing ${proj.preview}`,
            timestamp: Date.now()
        }]);
    }
  };

  const handleFileUpload = () => {
      // Mock file upload
      const mockFiles = ['datasheet_motor_v2.pdf', 'requirements.docx'];
      const randomFile = mockFiles[Math.floor(Math.random() * mockFiles.length)];
      setAttachedFiles(prev => [...prev, randomFile]);
  };

  const handleOnboardingComplete = (context: UserContext) => {
    setUserContext(context);
    setShowOnboarding(false);

    // Optional: Add a system welcome message based on context
    const welcomeMsg: Message = {
      id: crypto.randomUUID(),
      role: 'model',
      text: `Workspace configured for **${context.workflow}**. \nI've noted your access to ${context.resources.join(', ')} and your ${context.lifecycle} requirements. \n\nHow can I help you start your engineering task today?`,
      timestamp: Date.now()
    };
    setMessages([welcomeMsg]);
  };

  const renderArtifactContent = () => {
    if (!currentArtifact) return <div className="p-8 text-center text-gray-500">No artifact selected</div>;

    switch (currentArtifact.type) {
      case ArtifactType.BOM:
        return <BomView data={currentArtifact.content} onAction={handleSendMessage} />;
      case ArtifactType.CAD_CONCEPT:
        return <CadView data={currentArtifact.content} onAction={handleSendMessage} />;
      case ArtifactType.DOCUMENT:
      case ArtifactType.REVIEW_NOTE:
        return <DocumentView data={currentArtifact.content} />;
      default:
        return <div className="p-4">Unknown Artifact Type</div>;
    }
  };

  const getEmptyStateSuggestions = () => {
    switch (activePillar) {
      case 'concept':
        return [
          { 
              heading: "Heavy-duty Camera Mount", 
              prompt: "Create a CAD concept for a heavy-duty camera mount focused on vibration dampening.", 
              icon: <Box size={20}/> 
          },
          { 
              heading: "Compliant Gripper", 
              prompt: "Design a compliant mechanism for a soft robotics gripper.", 
              icon: <Cpu size={20}/> 
          },
          { 
              heading: "Waterproof Enclosure", 
              prompt: "Generate a concept for an IP67 water-resistant electronics enclosure.", 
              icon: <Shield size={20}/> 
          },
          { 
              heading: "Sheet Metal Bracket", 
              prompt: "Design a mounting bracket for a NEMA 17 stepper motor optimized for sheet metal fabrication.", 
              icon: <Layers size={20}/> 
          }
        ];
      case 'sourcing':
        return [
          { 
              heading: "Robotic Arm BOM", 
              prompt: "Draft a Bill of Materials for a 6-DOF robotic arm including servos, bearings, and fasteners.", 
              icon: <List size={20}/> 
          },
          { 
              heading: "Find Alternatives", 
              prompt: "Find in-stock alternatives for the STM32F405 microcontroller with matching footprint.", 
              icon: <Search size={20}/> 
          },
          { 
              heading: "Supply Chain Risk", 
              prompt: "Identify potential long lead-time components in a standard drone ESC design.", 
              icon: <AlertTriangle size={20}/> 
          },
          { 
              heading: "Cost Estimation", 
              prompt: "Estimate the production cost breakdown for 500 units of a Bluetooth LE beacon.", 
              icon: <DollarSign size={20}/> 
          }
        ];
      case 'copilot':
      default:
        return [
          { 
              heading: "Design Review", 
              prompt: "Review design assumptions for a high-temperature sensor enclosure.", 
              icon: <Eye size={20}/> 
          },
          { 
              heading: "Material Comparison", 
              prompt: "Explain the trade-offs between Aluminum 6061-T6 and 7075-T6 for aerospace brackets.", 
              icon: <Scale size={20}/> 
          },
          { 
              heading: "ISO Compliance", 
              prompt: "Summarize the key documentation requirements for ISO 13485 medical device compliance.", 
              icon: <FileText size={20}/> 
          },
          { 
              heading: "Torque Calculation", 
              prompt: "Calculate the required motor torque to lift a 5kg load using a 20mm radius pulley.", 
              icon: <Calculator size={20}/> 
          }
        ];
    }
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-white text-brand-darkBlue font-sans">
      {showOnboarding && <OnboardingModal onComplete={handleOnboardingComplete} />}
      <SettingsModal 
