                                    <div>
                                        <div className="font-semibold text-brand-darkBlue text-sm mb-1 group-hover:text-brand-blue">{suggestion.heading}</div>
                                        <div className="text-xs text-gray-500 leading-snug line-clamp-2">{suggestion.prompt}</div>
                                    </div>
                                </button>
                            ))}
