import { Plus } from "lucide-react";

export const AddComponentModal = ({
  isOpen,
  onClose,
  onAdd,
}: {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (details: { name: string; category: string; specs: string }) => void;
}) => {
  const [name, setName] = useState("");
  const [category, setCategory] = useState("");
  const [specs, setSpecs] = useState("");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd({ name, category, specs });
    setName("");
    setCategory("");
    setSpecs("");
    onClose();
  };
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex justify-center items-center z-50">
      <div className="bg-white rounded-lg p-6 shadow-xl w-full max-w-lg">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold">Add Component</h2>
          <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-100 transition-colors">
            <X size={16} />
          </button>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Component Name</label>
            <input
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full border rounded-lg p-2 text-sm outline-none focus:ring-2 focus:ring-brand-blue/20"
              placeholder="e.g. Gear, Motor"
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Category</label>
            <input
              type="text"
              required
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              className="w-full border rounded-lg p-2 text-sm outline-none focus:ring-2 focus:ring-brand-blue/20"
              placeholder="e.g. Mechanical, Electrical"
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Key Specifications</label>
            <textarea
              required
              value={specs}
              onChange={(e) => setSpecs(e.target.value)}
              className="w-full border rounded-lg p-2 text-sm outline-none focus:ring-2 focus:ring-brand-blue/20"
              rows={3}
              placeholder="e.g. Aluminum 6061, 5mm thickness, CNC machined"
            />
          </div>
          <button
            type="submit"
            className="w-full py-2 bg-brand-blue text-white rounded-lg font-bold text-sm hover:bg-blue-700 transition-colors flex items-center justify-center gap-2"
          >
            <Plus size={16} /> Add to Concept
          </button>
        </form>
      </div>
    </div>
  );
};
