                autoFocus 
                required 
                value={name} 
                onChange={e => setName(e.target.value)} 
                className="w-full border border-gray-300 rounded-lg p-2.5 text-sm outline-none focus:ring-2 focus:ring-brand-blue/20 focus:border-brand-blue transition-all" 
