                />
              </div>
            </div>
          )}

          <button 
            type="submit" 
            className="w-full py-2.5 bg-brand-blue text-white rounded-lg font-bold text-sm hover:bg-blue-700 transition-colors flex items-center justify-center gap-2 shadow-sm mt-2"
          >
            <Plus size={16} /> Add to Concept
          </button>
        </form>
      </div>
    </div>
  );
};

