interface TutorialOverlayProps {
  onComplete: () => void;
}

export const TutorialOverlay: React.FC<TutorialOverlayProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);

  const steps = [
    {
      title: "Select your Mode",
      desc: "Switch between Concept Formation, Sourcing, and Copilot modes in the sidebar to tailor the AI's engineering capabilities.",
      // Positioned near the sidebar on desktop, centered on mobile
      positionClass: "md:top-32 md:left-72 top-20 left-1/2 -translate-x-1/2 md:translate-x-0", 
      arrow: "left",
      icon: <Cpu size={24} className="text-purple-500" />
    },
    {
      title: "Engineering Chat",
      desc: "Ask complex questions, attach datasheets, or request calculations here. The AI maintains context of your engineering constraints.",
      // Positioned above the input area
      positionClass: "bottom-40 left-1/2 -translate-x-1/2", 
      arrow: "down",
      icon: <MessageSquare size={24} className="text-blue-500" />
    },
    {
      title: "Intelligent Artifacts",
      desc: "Buildables generates interactive CAD concepts, BOMs, and Documents. They will appear here in the split-view panel.",
      // Positioned on the right side where the panel opens
      positionClass: "md:top-1/2 md:right-[20%] md:-translate-y-1/2 top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2", 
      arrow: "right",
      icon: <Database size={24} className="text-orange-500" />
    }
  ];

  const current = steps[step];

  const handleNext = () => {
    if (step < steps.length - 1) {
      setStep(step + 1);
    } else {
      onComplete();
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/30 backdrop-blur-[2px] transition-all animate-in fade-in duration-500">
      <div className={`absolute ${current.positionClass} transition-all duration-500 ease-in-out`}>
        <div className="bg-white p-6 rounded-xl shadow-2xl border border-gray-200 w-80 animate-in zoom-in-95 fade-in duration-300 relative">

            {/* Contextual Arrows (Hidden on mobile for simplicity in this implementation) */}
            <div className="hidden md:block">
                {current.arrow === 'left' && <div className="absolute top-8 -left-3 w-6 h-6 bg-white transform rotate-45 border-l border-b border-gray-200"></div>}
                {current.arrow === 'down' && <div className="absolute -bottom-3 left-1/2 -translate-x-1/2 w-6 h-6 bg-white transform rotate-45 border-r border-b border-gray-200"></div>}
                {current.arrow === 'right' && <div className="absolute top-1/2 -right-3 -translate-y-1/2 w-6 h-6 bg-white transform rotate-45 border-r border-t border-gray-200"></div>}
            </div>

            <div className="flex items-center gap-3 mb-3">
                <div className="p-2 bg-gray-50 rounded-lg border border-gray-100 shadow-sm">
                    {current.icon}
                </div>
                <div>
                    <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Step {step + 1} of {steps.length}</span>
                    <h3 className="font-bold text-brand-darkBlue text-lg leading-tight">{current.title}</h3>
                </div>
            </div>

            <p className="text-sm text-gray-600 mb-6 leading-relaxed">
                {current.desc}
            </p>

            <div className="flex justify-between items-center pt-2">
                <div className="flex gap-1.5">
                    {steps.map((_, i) => (
                        <div key={i} className={`h-1.5 rounded-full transition-all duration-300 ${i === step ? 'w-6 bg-brand-blue' : 'w-1.5 bg-gray-200'}`} />
                    ))}
                </div>
                <div className="flex gap-2">
                    <button onClick={onComplete} className="text-xs font-bold text-gray-400 hover:text-gray-600 px-3 py-2 transition-colors">Skip</button>
                    <button 
                        onClick={handleNext}
                        className="bg-brand-darkBlue text-white px-5 py-2 rounded-lg text-xs font-bold hover:bg-brand-blue transition-colors flex items-center gap-2 shadow-lg hover:shadow-xl hover:-translate-y-0.5 transform"
                    >
                        {step === steps.length - 1 ? 'Get Started' : 'Next'}
                        <ArrowRight size={12} />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

