import React, { useState, useEffect } from 'react';
import { ArrowRight, ChevronLeft, Cpu, MessageSquare, Database, X, Sparkles } from 'lucide-react';

interface TutorialOverlayProps {
  onComplete: () => void;
}

export const TutorialOverlay: React.FC<TutorialOverlayProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    // Smooth fade in
    const timer = setTimeout(() => setIsVisible(true), 100);
    return () => clearTimeout(timer);
  }, []);

  const steps = [
    {
      title: "Welcome to Buildables v3",
      desc: "Your AI-powered mechanical engineering companion. Let's take a quick tour to get you up to speed with your new workspace.",
      positionClass: "top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2",
      mobilePosition: "top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2",
      arrow: null,
      icon: <Sparkles size={24} className="text-yellow-500" />,
      beacon: null
    },
    {
      title: "Select your Mode",
      desc: "Switch between 'Concept Formation' for ideation, 'Sourcing' for procurement, and 'Copilot' for general tasks using the sidebar.",
      positionClass: "top-[240px] left-[280px]",
      mobilePosition: "top-20 left-1/2 -translate-x-1/2",
      arrow: "left",
      icon: <Cpu size={24} className="text-purple-500" />,
      beacon: { top: '260px', left: '128px' } // Points to sidebar center-ish
    },
    {
      title: "Engineering Chat",
      desc: "This is your main command center. Ask questions, run calculations, or attach specs and datasheets for deep analysis.",
      positionClass: "bottom-[180px] left-1/2 -translate-x-1/2",
      mobilePosition: "bottom-40 left-1/2 -translate-x-1/2",
      arrow: "down",
      icon: <MessageSquare size={24} className="text-blue-500" />,
      beacon: { bottom: '80px', left: '50%' } // Points above input
    },
    {
      title: "Intelligent Artifacts",
      desc: "Generated CAD models, BOMs, and Documents will appear here. You can interact with them, compare parts, and export data.",
      positionClass: "top-1/2 right-[100px] -translate-y-1/2",
      mobilePosition: "top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2",
      arrow: "right",
      icon: <Database size={24} className="text-orange-500" />,
      beacon: { top: '50%', right: '40px' } // Points to right panel area
    }
  ];

  const current = steps[step];

  const handleNext = () => {
    if (step < steps.length - 1) {
      setStep(step + 1);
    } else {
      handleClose();
    }
  };

  const handleBack = () => {
    if (step > 0) {
      setStep(step - 1);
    }
  };

  const handleClose = () => {
    setIsVisible(false);
    setTimeout(onComplete, 500);
  };

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight') {
         if (step < steps.length - 1) setStep(s => s + 1);
         else handleClose();
      }
      if (e.key === 'ArrowLeft' && step > 0) setStep(s => s - 1);
      if (e.key === 'Escape') handleClose();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [step, steps.length]);

  return (
    <div className={`fixed inset-0 z-[60] transition-opacity duration-500 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>
      {/* Backdrop */}
      <div className="absolute inset-0 bg-brand-darkBlue/40 backdrop-blur-[2px]" onClick={handleClose} />

      {/* Beacon Animation (Desktop Only) */}
      {current.beacon && (
          <div 
            className="absolute z-10 hidden md:block transition-all duration-500 ease-in-out pointer-events-none" 
            style={{ 
                top: current.beacon.top, 
                left: current.beacon.left, 
                bottom: current.beacon.bottom, 
                right: current.beacon.right 
            }}
          >
            <span className="relative flex h-8 w-8 -translate-x-1/2 -translate-y-1/2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-brand-orange opacity-75"></span>
                <span className="relative inline-flex rounded-full h-8 w-8 bg-brand-orange/40 border-2 border-white shadow-lg"></span>
            </span>
          </div>
      )}

      {/* Card Container (Desktop) */}
      <div className={`absolute ${current.positionClass} transition-all duration-500 ease-in-out hidden md:block z-20`}>
        <TutorialCard 
            step={step} 
            total={steps.length} 
            data={current} 
            onNext={handleNext} 
            onBack={handleBack} 
            onSkip={handleClose} 
        />
      </div>

      {/* Card Container (Mobile) */}
      <div className={`absolute ${current.mobilePosition} w-[90%] max-w-sm transition-all duration-500 ease-in-out md:hidden block z-20`}>
         <TutorialCard 
            step={step} 
            total={steps.length} 
            data={current} 
            onNext={handleNext} 
            onBack={handleBack} 
            onSkip={handleClose} 
            isMobile
        />
      </div>
    </div>
  );
};

