  specs: Record<string, string>;
  isReference?: boolean;
}

export interface LibraryPart {
  id: string;
  partNumber: string;
  name: string;
  manufacturer: string;
  category: string;
  description: string;
  status: 'Active' | 'Obsolete' | 'Prototyping' | 'In Stock';
