  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Click outside to close tool menu
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (toolMenuRef.current && !toolMenuRef.current.contains(event.target as Node)) {
            setIsToolMenuOpen(false);
        }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleSendMessage = async (text: string = input) => {
    if ((!text.trim() && attachedFiles.length === 0 && !imageAttachment) || isLoading) return;

    let fullText = text;
    if (attachedFiles.length > 0) {
        fullText += `\n\n[Attached Context Files: ${attachedFiles.join(', ')}]`;
    }
    if (imageAttachment && !fullText.includes("image")) {
        // If image is attached but no specific prompt, ensure context knows
        // The service handles the actual image data, this is for the UI history
    }

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: fullText,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachedFiles([]); // Clear attachments

    // Capture image for service before clearing state
    const currentImage = imageAttachment;
    setImageAttachment(null);

    setIsLoading(true);

    // Prepare history for API
    const history = messages.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }));

    // Pass userContext and Image to the service
    const response = await sendMessageToGemini(history, userMsg.text, userContext, activePillar, currentImage);

    const modelMsg: Message = {
      id: crypto.randomUUID(),
      role: 'model',
      text: response.text,
      timestamp: Date.now(),
      relatedArtifactId: response.artifact?.id
    };

    setMessages(prev => [...prev, modelMsg]);
    setIsLoading(false);

    if (response.artifact) {
      setCurrentArtifact(response.artifact);
      setIsArtifactPanelOpen(true);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

