import React, { useState } from 'react';
import { LibraryPart } from '../types';
import { Search, Filter, Plus, Package, MapPin, Tag, MoreHorizontal, FileText, LayoutGrid, List } from 'lucide-react';

interface PartsLibraryProps {
  parts: LibraryPart[];
  onViewPart: (part: LibraryPart) => void;
}

export const PartsLibrary: React.FC<PartsLibraryProps> = ({ parts, onViewPart }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('All');
  const [viewMode, setViewMode] = useState<'list' | 'grid'>('list');

  const categories = ['All', ...Array.from(new Set(parts.map(p => p.category)))];

  const filteredParts = parts.filter(part => {
    const matchesSearch = 
      part.partNumber.toLowerCase().includes(searchTerm.toLowerCase()) || 
      part.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      part.manufacturer.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesCategory = filterCategory === 'All' || part.category === filterCategory;

    return matchesSearch && matchesCategory;
  });

  const getStatusColor = (status: LibraryPart['status']) => {
    switch (status) {
      case 'Active': return 'bg-green-100 text-green-700 border-green-200';
      case 'In Stock': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'Prototyping': return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'Obsolete': return 'bg-red-100 text-red-700 border-red-200';
      case 'On Order': return 'bg-orange-100 text-orange-700 border-orange-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  return (
    <div className="flex-1 h-full overflow-hidden flex flex-col bg-gray-50 font-sans">
      {/* Header */}
      <div className="bg-white border-b border-gray-200 px-8 py-6">
        <div className="flex justify-between items-center mb-6">
