            <div className="absolute right-0 top-full mt-2 w-48 bg-white border border-gray-200 rounded-lg shadow-xl z-20 hidden group-hover:block animate-in fade-in zoom-in-95 duration-150">
               {categories.map(cat => (
                 <button 
                    key={cat}
