                                        {file}
                                        <button onClick={() => setAttachedFiles(prev => prev.filter(f => f !== file))} className="text-gray-400 hover:text-red-500">
                                            <XCircle size={14} />
                                        </button>
                                    </div>
                                ))}
                                {imageAttachment && (
                                    <div className="relative group animate-in fade-in zoom-in duration-200">
