                                            <X size={10} />
                                        </button>
                                    </div>
                                )}
                            </div>
                        )}

                        <div className="flex items-end">
                            {/* Tools Button */}
                            <div className="pl-3 pb-3">
                                <button 
                                    onClick={() => setIsToolMenuOpen(!isToolMenuOpen)}
