                                >
                                    <Plus size={18} />
                                </button>
                            </div>

                            <textarea
                                value={input}
                                onChange={(e) => setInput(e.target.value)}
                                onKeyDown={handleKeyDown}
                                placeholder={`Ask ${activePillar === 'concept' ? 'Concept Formation' : activePillar === 'sourcing' ? 'Sourcing' : 'Copilot'}...`}
