                                        onClick={() => handleSendMessage()}
                                        disabled={(!input.trim() && attachedFiles.length === 0 && !imageAttachment) || isLoading}
                                        className={`p-2 rounded-lg transition-all duration-200 ${input.trim() || attachedFiles.length > 0 || imageAttachment ? 'bg-brand-orange text-white shadow-md hover:bg-orange-600' : 'bg-gray-100 text-gray-300'}`}
                                    >
                                        <ArrowRight size={18} />
                                    </button>
                                </div>
                            </div>
                        </div>
                        <p className="text-center text-[10px] text-gray-400 mt-3 font-medium tracking-wide">Buildables v3 can make mistakes. Verify component specs.</p>
                    </div>
                </div>
            </>
      );
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#fbfbfa] text-brand-darkBlue font-sans selection:bg-brand-orange/20">
      {showOnboarding && <OnboardingModal onComplete={handleOnboardingComplete} />}
      {showTutorial && <TutorialOverlay onComplete={() => setShowTutorial(false)} />}

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
