      {/* Main Content Area */}
      <div className={`flex-1 flex flex-col h-full transition-all duration-300 relative ${isArtifactPanelOpen && currentView !== 'dashboard' && currentView !== 'library' ? 'w-1/2' : 'w-full'} ${currentView !== 'chat' && isArtifactPanelOpen ? 'md:pr-[45%]' : ''}`}>

