import React, { useState, useEffect } from 'react';
import { ArrowRight, ChevronLeft, Cpu, MessageSquare, Database, X, Sparkles, LayoutGrid, Package, Wrench, Search } from 'lucide-react';

interface TutorialOverlayProps {
