      case 'In Stock': return 'bg-blue-50 text-blue-700 border-blue-100';
      case 'Prototyping': return 'bg-purple-50 text-purple-700 border-purple-100';
      case 'Obsolete': return 'bg-red-50 text-red-700 border-red-100';
